<script>
const diagnoses={slow:['Lentidão do computador','Verifique espaço livre e programas iniciados automaticamente. Evite baixar “otimizadores” desconhecidos.','Software / desempenho'],network:['Problemas de conexão','Teste outro dispositivo e reinicie o roteador, se for seguro. Confira cabos e indicadores de sinal.','Redes e conectividade'],startup:['Equipamento não inicializa','Confira alimentação e conexões externas. Se houver cheiro de queimado, não ligue novamente.','Hardware / diagnóstico'],security:['Possível incidente de segurança','Desconecte o dispositivo de redes se suspeitar de infecção e altere senhas a partir de um aparelho confiável.','Segurança digital']};
document.querySelectorAll('[data-diagnosis]').forEach(btn=>btn.addEventListener('click',()=>{const v=diagnoses[btn.dataset.diagnosis];document.getElementById('diagnosticTitle').textContent=v[0];document.getElementById('diagnosticText').textContent=v[1];document.getElementById('diagnosticCategory').textContent=v[2];const panel=document.getElementById('diagnosticResult');panel.hidden=false;panel.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});}));</script>
